SELECT 'core-2026-09-v4','question-tags','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"question-tags","title":"Question tags and agreement in responses","level":"B1","order":52,"summary":"Add a short checking question and match its auxiliary, pronoun and polarity to the statement.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Opposite polarity in a checking tag","Reuse the auxiliary","Keep number and person","Requests and special tags"],"rules":[{"title":"Opposite polarity in a checking tag","explanation":"A usual checking tag is negative after a positive statement and positive after a negative statement. Intonation helps show whether the speaker expects agreement or is genuinely checking. Other tag patterns exist in conversation, but the ordinary opposite-polarity form is a useful starting point.","pattern":"She is ready, **isn’t she**? / She isn’t ready, **is she**?","commonMistakes":["A negative statement can contain never or nobody without the word not. Its checking tag is normally positive."],"examples":["“She prepares the visitor guide every week, **doesn’t she**?”","“She restores the old portrait every week, **doesn’t she**?”"],"skill":"form"},{"title":"Reuse the auxiliary","explanation":"Match the tense and auxiliary of the statement. If it has no auxiliary and is ordinary present or past simple, use do, does or did. Replace a noun subject with an appropriate pronoun.","pattern":"The guide arrived, **didn’t she**?","commonMistakes":["Do not use is as a universal tag auxiliary; it must match the clause."],"examples":["“They did not prepare the visitor guide yesterday, **did they**?”","“They did not restore the old portrait yesterday, **did they**?”"],"skill":"meaning"},{"title":"Keep number and person","explanation":"The tag’s pronoun refers to the statement’s subject, not the nearest noun. Everyone commonly takes they in a tag. There stays there after an existential statement. Standard conversation often uses aren’t I after I am.","pattern":"There is a seat, **isn’t there**? / I’m late, **aren’t I**?","commonMistakes":["Everyone is ready, aren’t they? combines singular agreement in the main clause with singular they in the tag."],"examples":["“We are preparing the visitor guide, **aren’t we**?”","“We are restoring the old portrait, **aren’t we**?”"],"skill":"contrast"},{"title":"Requests and special tags","explanation":"Commands often use will you or would you as a softening tag. Let’s commonly takes shall we. These patterns do not follow the simple positive/negative statement rule. Tags in these exercises are ordinary checking tags unless a special function is named.","pattern":"Let’s leave, **shall we**? / Close the door, **will you**?","commonMistakes":["A comma normally separates a written tag from the statement."],"examples":["“Let’s prepare the visitor guide, **shall we**?”","“Let’s restore the old portrait, **shall we**?”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-question-tags"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Add a short checking question and match its auxiliary, pronoun and polarity to the statement.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Opposite polarity in a checking tag","explanation":"A usual checking tag is negative after a positive statement and positive after a negative statement. Intonation helps show whether the speaker expects agreement or is genuinely checking. Other tag patterns exist in conversation, but the ordinary opposite-polarity form is a useful starting point.","pattern":"She is ready, **isn’t she**? / She isn’t ready, **is she**?","commonMistakes":["A negative statement can contain never or nobody without the word not. Its checking tag is normally positive."],"examples":["“She prepares the visitor guide every week, **doesn’t she**?”","“She restores the old portrait every week, **doesn’t she**?”"],"skill":"form","id":"question-tags-foundation-1","domain":"sentence-types","referenceIds":["bc-question-tags"],"readingVersion":"core-2026-09-v3"},{"title":"Reuse the auxiliary","explanation":"Match the tense and auxiliary of the statement. If it has no auxiliary and is ordinary present or past simple, use do, does or did. Replace a noun subject with an appropriate pronoun.","pattern":"The guide arrived, **didn’t she**?","commonMistakes":["Do not use is as a universal tag auxiliary; it must match the clause."],"examples":["“They did not prepare the visitor guide yesterday, **did they**?”","“They did not restore the old portrait yesterday, **did they**?”"],"skill":"meaning","id":"question-tags-foundation-2","domain":"sentence-types","referenceIds":["bc-question-tags"],"readingVersion":"core-2026-09-v3"},{"title":"Keep number and person","explanation":"The tag’s pronoun refers to the statement’s subject, not the nearest noun. Everyone commonly takes they in a tag. There stays there after an existential statement. Standard conversation often uses aren’t I after I am.","pattern":"There is a seat, **isn’t there**? / I’m late, **aren’t I**?","commonMistakes":["Everyone is ready, aren’t they? combines singular agreement in the main clause with singular they in the tag."],"examples":["“We are preparing the visitor guide, **aren’t we**?”","“We are restoring the old portrait, **aren’t we**?”"],"skill":"contrast","id":"question-tags-foundation-3","domain":"sentence-types","referenceIds":["bc-question-tags"],"readingVersion":"core-2026-09-v3"},{"title":"Requests and special tags","explanation":"Commands often use will you or would you as a softening tag. Let’s commonly takes shall we. These patterns do not follow the simple positive/negative statement rule. Tags in these exercises are ordinary checking tags unless a special function is named.","pattern":"Let’s leave, **shall we**? / Close the door, **will you**?","commonMistakes":["A comma normally separates a written tag from the statement."],"examples":["“Let’s prepare the visitor guide, **shall we**?”","“Let’s restore the old portrait, **shall we**?”"],"skill":"application","id":"question-tags-foundation-4","domain":"sentence-types","referenceIds":["bc-question-tags"],"readingVersion":"core-2026-09-v3"},{"domain":"usage","id":"tags-intonation-and-response","title":"Question-tag intonation, checking and social meaning","explanation":"A tag can ask for genuine confirmation, invite agreement or manage the tone of a remark. Rising or falling intonation often helps distinguish these purposes, but context also matters. Some tags are conventional exceptions to the basic polarity pattern, and invariant tags such as right? occur in informal conversation.","pattern":"You’re coming, **aren’t you**?","examples":["I’m late, **aren’t I**?","Close the door, **will you**?"],"commonMistakes":["A tag is not always a neutral request for information. Depending on tone, the same words can sound friendly, insistent, surprised or critical."],"referenceIds":["cambridge-spoken","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["She is ready, **isn’t she**? / She isn’t ready, **is she**?","The guide arrived, **didn’t she**?","There is a seat, **isn’t there**? / I’m late, **aren’t I**?","Let’s leave, **shall we**? / Close the door, **will you**?"],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["reported-questions"],"readingReferenceIds":["bc-question-tags","cambridge-spoken","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHE